import React from 'react';
import {createRoot} from 'react-dom/client';
import {CandidateStrengthGap} from '../../src/pages/dashboard/DriveManagement';
import '../../src/index.css';
import {collegeApi} from '../../src/api/collegeApi';

// Local UI fixture: uses the real production component with clearly labelled sample evidence.
collegeApi.get = async <T,>() => ({reports:[{drive_id:'local-preview',detail:{strengths:['Maintains a professional tone and communicates ideas clearly.','Explains technical decisions using concrete examples.','Responds constructively to follow-up questions.'],priority_improvement_areas:['Structure answers with context, action and measurable results.','Provide deeper evidence for technical trade-offs.','Practice concise summaries for complex problems.'],agent_breakdown:[{agent_type:'HR',score:72},{agent_type:'Domain',score:68},{agent_type:'Industry',score:70},{agent_type:'Manager',score:75}]}}]} as T);
createRoot(document.getElementById('root')!).render(<main className="min-h-screen bg-slate-50 p-6 sm:p-12 text-slate-900"><div className="mx-auto max-w-5xl"><p className="mb-3 text-sm text-indigo-700">Local UI preview · sample data</p><h1 className="mb-8 text-2xl font-bold">Placement drive · Interview results</h1><div data-testid="clipping-card" className="overflow-hidden rounded-xl border border-indigo-200 bg-white"><div className="border-b p-6"><h2 className="font-semibold">Preview Candidate</h2><p className="text-sm text-slate-500">Software Engineer · Sample drive</p></div><div className="p-6"><p className="mb-4 text-sm">AI recommendation <strong className="ml-2 rounded-full bg-amber-100 px-3 py-1 text-amber-800">Consider</strong></p><CandidateStrengthGap driveId="local-preview" candidate={{student_id:'local-preview',full_name:'Preview Candidate',roll_number:'PREVIEW',recommendation:'Consider'}} onOpenReport={()=>alert('Full report action invoked')}/></div></div><div className="mt-4 rounded-xl border bg-white p-6 text-slate-500">Next candidate card — the popup should stay fully visible above this card.</div></div></main>);
